type agreementNativeInfoOwner struct {
	Field, Code, Site, Root, Node int
}

// A physical word belongs to one complete declared fence-info segment.
func agreementNativeInfoOwners(native agreementNativeOwnerSource, check *agreementNativeCheckSource, sites []agreementNativeCodePayloadSite) ([]agreementNativeInfoOwner, bool) {
	var owners []agreementNativeInfoOwner
	used := make(map[graph.Span]bool)
	for fi, field := range check.Fields {
		if field.Code || field.Comment || field.Escaped || field.DefinitionOwner >= 0 || field.CodeOwner < 0 {
			continue
		}
		if field.CodeOwner >= len(native.Code) {
			return nil, false
		}
		code := native.Code[field.CodeOwner]
		switch code.Kind {
		case ast.KindCodeSpan.String(), ast.KindCodeBlock.String(), ast.KindFencedCodeBlock.String(), "FencedCodeBlockInfo":
		default:
			return nil, false
		}
		if code.Kind != "FencedCodeBlockInfo" || !slices.Contains(field.Targets, "A") {
			continue
		}
		if len(field.Targets) != 1 || code.Span.Start < 0 || code.Span.Stop <= code.Span.Start || field.Span.Start < code.Span.Start || field.Span.Stop > code.Span.Stop || field.Span.Stop <= field.Span.Start || used[field.Span] {
			return nil, false
		}
		candidate := -1
		for si := range sites {
			site := &sites[si]
			if site.Kind != ast.KindFencedCodeBlock.String() || !site.HasInfo || site.ParentKind != code.Parent || site.Info.Start != code.Span.Start || site.Info.Stop != code.Span.Stop {
				continue
			}
			if candidate >= 0 {
				return nil, false
			}
			candidate = si
		}
		if candidate < 0 {
			return nil, false
		}
		used[field.Span] = true
		owners = append(owners, agreementNativeInfoOwner{Field: fi, Code: field.CodeOwner, Site: candidate, Root: sites[candidate].Root, Node: sites[candidate].Node})
	}
	return owners, len(owners) > 0
}

// Private words change only the selected fence-info targets.
func agreementNativeInfoRename(body string, native agreementNativeOwnerSource, check *agreementNativeCheckSource, sites []agreementNativeCodePayloadSite) (string, []agreementNativeInfoOwner, []agreementNativeCodePayloadTarget, bool) {
	if strings.Contains(body, "q") {
		return "", nil, nil, false
	}
	owners, valid := agreementNativeInfoOwners(native, check, sites)
	if !valid {
		return "", nil, nil, false
	}
	private := []byte(body)
	var changes []agreementNativeCodePayloadTarget
	for _, owner := range owners {
		field := check.Fields[owner.Field]
		if native.Code[owner.Code].Span.Stop > len(body) || field.Span.Start < 0 || field.Span.Stop > len(body) || len(field.Word) < 4 || body[field.Span.Start:field.Span.Stop] != field.Word {
			return "", nil, nil, false
		}
		inner := field.Word[2 : len(field.Word)-2]
		link, ok := graph.ParseWikilink(inner)
		if !ok || strings.ContainsAny(inner, "[]\r\n") || strings.ContainsRune(inner, 96) || link.Target != "A" {
			return "", nil, nil, false
		}
		start := field.Span.Start + 2 + strings.Index(inner, link.Target)
		stop := start + len(link.Target)
		if start < field.Span.Start+2 || stop > field.Span.Stop-2 || body[start:stop] != link.Target {
			return "", nil, nil, false
		}
		name := strings.Repeat("q", len(link.Target))
		copy(private[start:stop], name)
		changes = append(changes, agreementNativeCodePayloadTarget{Window: owner.Code, Span: graph.Span{Start: start, Stop: stop}, Old: link.Target, New: name})
	}
	return string(private), owners, changes, true
}

func agreementNativeInfoCurrent(failures []agreementFailure) map[string]int {
	current := make(map[string]int)
	for i := range failures {
		f := &failures[i]
		switch f.Property {
		case "P0", "P1", "P2", "P4":
			current[agreementSignature(f)]++
		}
	}
	return current
}

