func agreementNativeInfoDifference(c agreementCase, f *agreementFailure, raw string, actual *agreementHTML, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || actual == nil || c.Title != "" || len(c.Companions) != 0 || f.Tuple.SourceRole != "" || f.Tuple.Target != "A" || f.Tuple.Section != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Multiplicity < 1 {
		return "", "", ""
	}
	switch f.Property {
	case "P1":
		if f.Identity != "citation-occurrences" || f.Direction != "judge-only" || f.Tuple.State != "" {
			return "", "", ""
		}
	case "P0":
		if f.Identity != "diagnostic-html" || f.Direction != "diagnostic-only" || f.Tuple.State != "wikilink-broken" {
			return "", "", ""
		}
	default:
		return "", "", ""
	}
	witnesses := agreementNativeInfoWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		if c.Body != w.Body {
			continue
		}
		if w.Selected[agreementSignature(f)] != 1 {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		sites := agreementNativeCodePayloadSites(c.Body)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, partsOK := agreementCodeWindowParts(raw)
		private, owners, changes, renameOK := agreementNativeInfoRename(c.Body, native, &check, sites)
		if !partsOK || !renameOK || !tree.Valid || private != w.Private || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(sites, w.Sites) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*actual, w.Page) || !cmp.Equal(owners, w.Owners) || !cmp.Equal(changes, w.Changes) || !maps.Equal(agreementNativeInfoCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		if f.Property == "P1" {
			if len(owners) != f.Multiplicity {
				return "", "", ""
			}
			return "debt", "#1011 stage 4", "judge"
		}
		if f.Multiplicity > len(owners) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page-diagnostic"
	}
	return "", "", ""
}

func TestAgreementNativeInfoSource(t *testing.T) {
	t.Parallel()
	witnesses := agreementNativeInfoWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			for _, body := range []string{w.Body, w.Private} {
				if diff := cmp.Diff(w.Native, agreementNativeOwnerReading(body)); diff != "" {
					t.Fatalf("caught: complete native info owners (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.Sites, agreementNativeCodePayloadSites(body)); diff != "" {
					t.Fatalf("caught: complete declared fence-info sites (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.HTML, agreementNativeHTMLAddressSites(body)); diff != "" {
					t.Fatalf("caught: complete HTML declarations beside info (-want +got):\n%s", diff)
				}
				tree := agreementNativeProseAddressTreeReading(body, nil)
				if diff := cmp.Diff(w.Tree, tree); !tree.Valid || diff != "" {
					t.Fatalf("caught: complete info declaration trees (-want +got):\n%s", diff)
				}
			}
			for _, tc := range []struct {
				Body    string
				Check   agreementNativeCheckSource
				Targets []string
			}{{w.Body, w.Check, w.Targets}, {w.Private, w.PrivateCheck, w.PrivateTargets}} {
				if diff := cmp.Diff(tc.Check, agreementNativeCheckReading(tc.Body, w.Native)); diff != "" {
					t.Fatalf("caught: complete physical info fields (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(tc.Targets, judge.LinkTargets(tc.Body)); diff != "" {
					t.Fatalf("caught: complete public check targets (-want +got):\n%s", diff)
				}
			}
			private, owners, changes, ok := agreementNativeInfoRename(w.Body, w.Native, &w.Check, w.Sites)
			if !ok || private != w.Private || !cmp.Equal(owners, w.Owners) || !cmp.Equal(changes, w.Changes) {
				t.Fatal("caught: exact declared info owner map and target-only bytes")
			}
		})
	}
}

func TestAgreementNativeInfoPublic(t *testing.T) {
	t.Parallel()
	witnesses := agreementNativeInfoWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			for _, tc := range []struct {
				Name, Body string
				Signatures map[string]int
			}{{"original", w.Body, w.Signatures}, {"private", w.Private, w.PrivateSignatures}} {
				t.Run(tc.Name, func(t *testing.T) {
					raw, page := agreementIsolatedPage(t, agreementCase{Body: tc.Body})
					if diff := cmp.Diff(w.Page, page); diff != "" {
						t.Fatalf("caught: complete unchanged info public ledger (-want +got):\n%s", diff)
					}
					parts, ok := agreementCodeWindowParts(raw.HTML)
					if diff := cmp.Diff(w.Parts, parts); !ok || diff != "" {
						t.Fatalf("caught: complete unchanged info code payloads (-want +got):\n%s", diff)
					}
					failures := agreementPageFailures(tc.Body, &raw, &page)
					failures = append(failures, agreementFragmentFailures(t, []agreementCase{{Body: tc.Body}}, []agreementHTML{page})[0]...)
					if !maps.Equal(tc.Signatures, agreementNativeInfoCurrent(failures)) {
						t.Fatal("caught: complete original and private info signed pools")
					}
				})
			}
			expected := maps.Clone(w.Signatures)
			for sig, count := range w.Selected {
				expected[sig] -= count
				if expected[sig] == 0 {
					delete(expected, sig)
				}
				projected := strings.Replace(sig, "Target:A Section:", "Target:q Section:", 1)
				if projected == sig {
					t.Fatal("info signed substitution setup")
				}
				expected[projected] += count
			}
			if !maps.Equal(expected, w.PrivateSignatures) {
				t.Fatal("caught: every unselected public info receipt must stay identical")
			}
		})
	}
}

func TestAgreementNativeInfoDifferences(t *testing.T) {
	t.Parallel()
	for _, w := range agreementNativeInfoWitnesses() {
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			c := agreementCase{Body: w.Body}
			raw, page := agreementIsolatedPage(t, c)
			failures := agreementPageFailures(c.Body, &raw, &page)
			failures = append(failures, agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{page})[0]...)
			seen := 0
			for _, f := range failures {
				if w.Selected[agreementSignature(&f)] != 1 {
					continue
				}
				seen++
				kind, authority, wrong := agreementNativeInfoDifference(c, &f, raw.HTML, &page, failures)
				wantAuthority, wantWrong := "#1011 stage 4", "judge"
				if f.Property == "P0" {
					wantAuthority, wantWrong = "#1011 stage 5", "page-diagnostic"
				}
				if kind != "debt" || authority != wantAuthority || wrong != wantWrong {
					t.Fatal("caught: info receipt lost its named source authority")
				}
				for _, alter := range []struct {
					Name   string
					Change func(*agreementFailure)
				}{
					{"identity", func(f *agreementFailure) { f.Identity = "other" }},
					{"direction", func(f *agreementFailure) { f.Direction = "other" }},
					{"target", func(f *agreementFailure) { f.Tuple.Target = "outside" }},
					{"role", func(f *agreementFailure) { f.Tuple.SourceRole = "other" }},
					{"section", func(f *agreementFailure) { f.Tuple.Section = "other" }},
					{"state", func(f *agreementFailure) { f.Tuple.State = "other" }},
					{"multiplicity", func(f *agreementFailure) { f.Multiplicity++ }},
					{"fragment", func(f *agreementFailure) { f.Fragment = "other" }},
					{"cut", func(f *agreementFailure) { f.Cut = "other" }},
					{"page", func(f *agreementFailure) { f.PagePresent = true }},
					{"judge", func(f *agreementFailure) { f.JudgeAccepted = true }},
					{"excerpt", func(f *agreementFailure) { f.ExcerptFound = true }},
				} {
					t.Run(alter.Name, func(t *testing.T) {
						changed := f
						alter.Change(&changed)
						k, a, w := agreementNativeInfoDifference(c, &changed, raw.HTML, &page, failures)
						if k != "" || a != "" || w != "" {
							t.Fatal("caught: info borrowed another signed receipt")
						}
					})
				}
				for _, other := range []agreementCase{{Body: w.Body + "\n"}, {Body: w.Body, Title: "A"}, {Body: w.Body, Companions: capturedBodies{"Notes/Other.md": "outside"}}} {
					k, a, v := agreementNativeInfoDifference(other, &f, raw.HTML, &page, failures)
					if k != "" || a != "" || v != "" {
						t.Fatal("caught: info borrowed another complete body or context")
					}
				}
				changed := page
				changed.Headings = append(slices.Clone(page.Headings), "outside")
				k, a, v := agreementNativeInfoDifference(c, &f, raw.HTML, &changed, failures)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: info borrowed another whole public ledger")
				}
				for i, fragment := range failures {
					if fragment.Property != "P4" {
						continue
					}
					missing := slices.Delete(slices.Clone(failures), i, i+1)
					k, a, v = agreementNativeInfoDifference(c, &f, raw.HTML, &page, missing)
					if k != "" || a != "" || v != "" {
						t.Fatal("caught: info borrowed an incomplete P4 signed pool")
					}
				}
				extra := append(slices.Clone(failures), f)
				k, a, v = agreementNativeInfoDifference(c, &f, raw.HTML, &page, extra)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: info borrowed another whole signed pool")
				}
				k, a, v = agreementNativeInfoDifference(c, &f, raw.HTML+"<code>outside</code>", &page, failures)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: info borrowed changed field-free code text")
				}
			}
			if seen != len(w.Selected) {
				t.Fatal("info selected receipt setup")
			}
			if len(w.Selected) == 1 {
				f := agreementFailure{Property: "P0", Identity: "diagnostic-html", Tuple: agreementCitation{Target: "A", State: "wikilink-broken"}, Direction: "diagnostic-only", Multiplicity: 1}
				k, a, v := agreementNativeInfoDifference(c, &f, raw.HTML, &page, failures)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: info borrowed an absent diagnostic face")
				}
			}
		})
	}
}

func TestAgreementNativeInfoOwnershipRefusals(t *testing.T) {
	w := agreementNativeInfoWitnesses()[0]
	field := w.Owners[0].Field
	code := w.Owners[0].Code
	site := w.Owners[0].Site
	for _, tc := range []struct {
		Name   string
		Native agreementNativeOwnerSource
		Check  agreementNativeCheckSource
		Sites  []agreementNativeCodePayloadSite
		Change func(*agreementNativeOwnerSource, *agreementNativeCheckSource, []agreementNativeCodePayloadSite)
	}{
		{"missing physical fields", w.Native, agreementNativeCheckSource{}, w.Sites, nil},
		{"other declared code kind", w.Native, w.Check, w.Sites, func(n *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ []agreementNativeCodePayloadSite) {
			n.Code[code].Kind = ast.KindFencedCodeBlock.String()
			c.Fields = []agreementNativeCheckField{c.Fields[field]}
		}},
		{"other site kind", w.Native, w.Check, w.Sites, func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, s []agreementNativeCodePayloadSite) {
			s[site].Kind = ast.KindRawHTML.String()
		}},
		{"wrong span start", w.Native, w.Check, w.Sites, func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, s []agreementNativeCodePayloadSite) {
			s[site].Info.Start++
		}},
		{"outside field start", w.Native, w.Check, w.Sites, func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ []agreementNativeCodePayloadSite) {
			c.Fields[field].Span.Start = w.Native.Code[code].Span.Start - 1
		}},
		{"missing site", w.Native, w.Check, nil, nil},
		{"ambiguous site", w.Native, w.Check, append(slices.Clone(w.Sites), w.Sites[site]), nil},
		{"unknown kind", w.Native, w.Check, w.Sites, func(n *agreementNativeOwnerSource, _ *agreementNativeCheckSource, _ []agreementNativeCodePayloadSite) {
			n.Code[code].Kind = "RawHTML"
		}},
		{"outside field", w.Native, w.Check, w.Sites, func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ []agreementNativeCodePayloadSite) {
			c.Fields[field].Span.Stop = w.Native.Code[code].Span.Stop + 1
		}},
		{"missing info", w.Native, w.Check, w.Sites, func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, s []agreementNativeCodePayloadSite) {
			s[site].HasInfo = false
		}},
		{"wrong parent", w.Native, w.Check, w.Sites, func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, s []agreementNativeCodePayloadSite) {
			s[site].ParentKind = "other"
		}},
		{"wrong span", w.Native, w.Check, w.Sites, func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, s []agreementNativeCodePayloadSite) {
			s[site].Info.Stop++
		}},
		{"duplicate field", w.Native, w.Check, w.Sites, func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ []agreementNativeCodePayloadSite) {
			c.Fields = append(c.Fields, c.Fields[field])
		}},
	} {
		t.Run(tc.Name, func(t *testing.T) {
			n := tc.Native
			n.Code = slices.Clone(n.Code)
			c := tc.Check
			c.Fields = slices.Clone(c.Fields)
			s := slices.Clone(tc.Sites)
			if tc.Change != nil {
				tc.Change(&n, &c, s)
			}
			if _, ok := agreementNativeInfoOwners(n, &c, s); ok {
				t.Fatal("caught: info borrowed an absent, ambiguous or partial declaration")
			}
		})
	}
	if _, _, _, ok := agreementNativeInfoRename(w.Body+"q", w.Native, &w.Check, w.Sites); ok {
		t.Fatal("caught: info borrowed an existing private namespace")
	}
	c := w.Check
	c.Fields = slices.Clone(c.Fields)
	c.Fields[field].Word = "[[A\nB]]"
	if _, _, _, ok := agreementNativeInfoRename(w.Body, w.Native, &c, w.Sites); ok {
		t.Fatal("caught: info borrowed a changed physical word")
	}
}
